def score_pair(fc: Forecast, obs: Observation) -> dict[str, float]:
    """Score one forecast against the observation that realized it. RAISES on a charter
    violation (G1 point-assertion, G2 illegal use, G5 look-ahead leak)."""
    # G1 — distribution-only.
    if fc.point_asserted:
        raise ValueError(f"G1: forecast {fc.fid!r} asserts a deterministic point; unrepresentable (非終末論)")
    # G2 — non-speculative use.
    if fc.use not in ALLOWED_USE:
        raise ValueError(f"G2: forecast {fc.fid!r} use {fc.use!r} not in the non-speculative set {ALLOWED_USE[:5]}")
    # G5 — leak-free: the outcome must arrive STRICTLY AFTER the forecaster's info.
    if obs.observed_at <= fc.info_as_of:
        raise ValueError(
            f"G5 LEAK: obs {obs.oid!r} observed_at={obs.observed_at} is not strictly "
            f"after forecast {fc.fid!r} info_as_of={fc.info_as_of}; scoring would see the future"
        )

    out: dict[str, float] = {}
    if fc.dist_kind in ("gaussian", ":gaussian"):
        out["crps"] = gaussian_crps(fc.mean, fc.sd, obs.value)
        out["log_score"] = gaussian_logscore(fc.mean, fc.sd, obs.value)
        out["pit"] = gaussian_pit(fc.mean, fc.sd, obs.value)
    elif fc.dist_kind in ("quantile", ":quantile"):
        out["pinball"] = pinball_loss(fc.quantiles, obs.value)
        out["pit"] = quantile_pit(fc.quantiles, obs.value)
    elif fc.dist_kind in ("categorical", ":categorical"):
        out["brier"] = brier_score(fc.probs, obs.cls)
        out["log_score"] = categorical_logscore(fc.probs, obs.cls)
        out["pit"] = categorical_pit(fc.probs, obs.cls)
    elif fc.dist_kind in ("ensemble", ":ensemble"):
        out["crps"] = ensemble_crps(fc.members, obs.value)
        out["pit"] = ensemble_pit(fc.members, obs.value)
    else:
        raise ValueError(f"unknown dist_kind {fc.dist_kind!r}")
    return out

def series_histories(rows: list[dict]) -> dict[str, list[tuple[int, float]]]:
    """{series_id: [(observed_at, value), ...] sorted by observed_at} from a trail."""
    hist: dict[str, list[tuple[int, float]]] = {}
    for r in rows:
        if ":obs/series" in r and ":obs/observed-at" in r:
            hist.setdefault(r[":obs/series"], []).append(
                (int(r[":obs/observed-at"]), float(r[":obs/value"])))
    for sid in hist:
        hist[sid].sort()
    return hist

def forecast_next(sid: str, history: list[tuple[int, float]], target_at: int,
                  method: str = "climatology") -> Forecast | None:
    """Forecast series `sid` at `target_at` as a Gaussian distribution, using ONLY
    observations strictly before target_at (leak-free). Returns None if no prior history."""
    if method not in METHODS:
        raise ValueError(f"method must be one of {METHODS}, got {method!r}")
    prior = [(t, v) for (t, v) in history if t < target_at]
    if not prior:
        return None
    values = [v for _t, v in prior]
    info_as_of = max(t for t, _v in prior)            # G5 — newest fact the forecaster saw
    if method == "climatology":
        mu, sd = climatology_gaussian(values)
    else:
        mu, sd = persistence_gaussian(values)
    return Forecast(fid=f"fc.{sid}.{target_at}.{method}", dist_kind="gaussian",
                    info_as_of=info_as_of, use=":resilience", point_asserted=False,
                    mean=round(mu, 4), sd=round(sd, 6))

def compare_methods(rows: list[dict]) -> dict:
    """Rolling-origin backtest for every method → {method: summary}. The honest, all-origins
    method comparison (no cherry-picked target, leak-free at each origin)."""
    return {m: backtest_rolling(rows, m) for m in METHODS}

def render_edn(recs):
    def v(x):
        if isinstance(x, list):
            return "[" + " ".join(f'"{i}"' for i in x) + "]"
        if isinstance(x, str):
            return x if x.startswith(":") else f'"{x}"'
        return str(x)
    L = [";; watatsuna → watatsumi resilience fleet plan (GENERATED). :plan/* recommendations.",
         ";; G2/N8: redundancy + repair + monitor ONLY. ADR-2606012600. DO NOT hand-edit.", "["]
    for r in recs:
        L.append(" {" + " ".join(f"{k} {v(val)}" for k, val in r.items()) + "}")
    L.append("]")
    return "\n".join(L) + "\n"

def _strip_comments(s: str) -> str:
    out = []
    in_str = False
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if in_str:
            out.append(c)
            if c == '"' and s[i - 1] != "\\":
                in_str = False
            i += 1
            continue
        if c == '"':
            in_str = True
            out.append(c)
            i += 1
            continue
        if c == ";":
            while i < n and s[i] != "\n":
                i += 1
            continue
        out.append(c)
        i += 1
    return "".join(out)

def _top_level_entities(s: str):
    """Yield each top-level {...} map literal inside the outer [ ... ] vector."""
    s = _strip_comments(s)
    start = s.find("[")
    if start < 0:
        return
    depth = 0
    buf: list = []
    in_str = False
    for c in s[start + 1:]:
        if in_str:
            buf.append(c)
            if c == '"':
                in_str = False
            continue
        if c == '"':
            in_str = True
            buf.append(c)
            continue
        if c == "{":
            depth += 1
            buf.append(c)
        elif c == "}":
            depth -= 1
            buf.append(c)
            if depth == 0:
                yield "".join(buf).strip()
                buf = []
        elif depth > 0:
            buf.append(c)
